window.docContents[18].resolve({"/IndProp/#Logical-Foundations--IndProp___-Inductively-Defined-Propositions--Exercises-with-Inductive-Relations--More-Facts-about--Le--Facts-about--_LT_--and--___":{"contents":"\n\nThe \"strictly less than\" relation n < m can now be defined\nin terms of Nat.le.def Lt (n m : Nat) : Prop := Le (n + 1) m\n\nscoped infix:50 (priority := high) \" < \" => Lt\nThe ≥ operation is defined in terms of ≤.\nLean provides a theorem ge_iff_le allowing us to rewrite between them.def Ge (m n : Nat) : Prop := Le n m\n\nscoped infix:50 (priority := high) \" ≥ \" => Ge\n\nexample (m n : Nat) (h : m ≥ n) : n ≤ m := by\n  rw [Ge] at h\n  assumption\ntheorem lt_not_lt_zero (n : Nat) : ¬ n < 0 := by\n  intro h\n  inversion h\ntheorem lt_or_ge (n m : Nat) : n < m ∨ n ≥ m := by\n  sorry\ntheorem le_of_lt (n m : Nat) (h : n < m) : n ≤ m := by\n  sorry\ntheorem lt_and_lt_of_add_lt (n₁ n₂ m : Nat) (h : n₁ + n₂ < m) : n₁ < m ∧ n₂ < m := by\n  sorry\n\n\n","context":"Logical Foundations\u0009IndProp: Inductively Defined Propositions\u0009Exercises with Inductive Relations\u0009More Facts about  Le","header":"9.3.1.2. Facts about  <  and  ≥","id":"/IndProp/#Logical-Foundations--IndProp___-Inductively-Defined-Propositions--Exercises-with-Inductive-Relations--More-Facts-about--Le--Facts-about--_LT_--and--___"}});